"""Short offline conversational replies, separate from system-operation intents.

Estructura:
  - EXACT: frases completas (ya normalizadas) -> str o tupla de variantes.
  - PATTERNS: lista de (regex, variantes) para frases con muchas formas.
  - respond(): conserva las reglas originales y añade las nuevas al final.
  - unknown_reply(): fallback variado.
Las tuplas rotan con context.dialogue_turn para no repetir la misma frase.
"""
import re
from intelligence.rules import normalize


def _choice(options, context):
    turn = getattr(context, 'dialogue_turn', 0) if context else 0
    if context:
        context.dialogue_turn = turn + 1
    return options[turn % len(options)]


