# Elimina marcadores None para patrones delegados a otras capas
PATTERNS = [(rx, v) for rx, v in PATTERNS if v is not None]
_COMPILED = [(re.compile(rx), v) for rx, v in PATTERNS]


def _pick(answer, context):
    return _choice(answer, context) if isinstance(answer, tuple) else answer


def respond(text, context=None):
    s = normalize(text).strip(' .!?¿¡')
    s = re.sub(r'\bllmah\b', '', s).strip()
    s = re.sub(r'^(?:mmm+|aja+|jaja+|pues|oye)\s+', '', s)

    # 1) Frases exactas (originales + ampliadas)
    if s in EXACT:
        return _pick(EXACT[s], context)

    # Do not intercept complex or multi-word technical questions and instructions with generic chitchat
    words = s.split()
    if len(words) > 6 and any(kw in s for kw in ('script', 'programa', 'codigo', 'nginx', 'error', 'puertos', 'servicios', 'paso a paso', 'diagnos', 'analiza', 'configur', 'instala', 'json', 'revisa', 'servidor', 'pagina', 'sitio', 'procesos')):
        return None

    # 2) Reglas originales (se conservan intactas)
    if re.search(r'\b(no me pidas|no necesito tantas confirmaciones|no pidas confirmacion)\b', s):
        return 'Entendido: dejaré pasar tareas rutinarias y pediré confirmación solo para acciones importantes, como borrar datos, instalar paquetes, cambiar servicios o ejecutar acciones de alto impacto.'
    if re.search(r'\b(?:como|de que forma)\b.*\b(?:creo|crear|crea|se crean|hacer)\b.*\b(?:archivo|archivos|fichero|file)\b', s):
        return 'Sí: di «crea un archivo llamado notas.txt». También puedes usar `touch notas.txt`.'
    if re.search(r'\b(?:en que|que)\s+(?:me\s+)?puedes\s+ayudar\b|\bque puedes hacer por mi\b', s):
        return 'Con Linux, archivos, redes, desarrollo, cálculos y búsquedas web.'
    if re.search(r'\bproyecto\b', s) and re.search(r'\b(?:robusto|completo|mejorando|actualizamos|probamos)\b', s):
        return 'Sí. Cada ejemplo revela un fallo, lo corregimos y añadimos pruebas para que no vuelva. Así se fortalece paso a paso, aunque todavía tiene límites.'
    if re.search(r'\bme encanta\b', s):
        return '¡Me alegra! ¿Qué hacemos ahora?'
    if re.fullmatch(r'(?:mmm+\s+)?no lo se|no se', s):
        return 'No pasa nada. ¿Quieres que te sugiera algo?'
    if re.fullmatch(r'necesito\s+(?:que|uqe)', s):
        return 'Claro, ¿qué necesitas?'
    if re.search(r'\b(?:como|how)\b.*\b(?:aprender|learn)\b.*\b(?:programar|programming|code)\b', s):
        return 'Empieza con Python: practica variables, ciclos y funciones. Haz proyectos pequeños y aprende Git después.'
    if re.fullmatch(r'(?:aterrizamos|aterrizar|que significa aterrizamos)', s):
        return 'Quise decir «concretar la idea paso a paso». Pude decirlo más claro; evitaré esa expresión.'
    if re.search(r'\b(?:no te pregunte eso|no pregunte eso|eso no te pregunte|no era eso)\b', s):
        return 'Perdón, dejamos esa pregunta. ¿Qué querías decir?'
    if re.fullmatch(r'(?:ninguno|ninguna|ningun archivo|ninguna cosa)', s):
        return 'Entendido, dejamos eso.'
    if re.fullmatch(r'(?:por|porque)\s*\??', s):
        return '¿Qué parte quieres que explique?'
    if re.search(r'\b(?:solo dime|dime)\b.*\b(?:tu respuesta|la respuesta|what you found)\b', s):
        return None
    if re.search(r'\b(?:url|urls|enlaces|fuentes)\b', s) and re.search(r'\b(?:pequen|chiquit|menos notable|mas discre|solo la info|elimina|quita)\w*\b', s):
        return 'Entendido. En las búsquedas mostraré solo un resumen breve, sin enlaces ni lista de fuentes.'
    if re.search(r'\bciberseguridad\b', s) and re.search(r'\b(escanear|scan|nmap)\b', s):
        return EXACT['por que en ciberseguridad solo puedes escanear']
    if s.startswith('porque solo dices eso'):
        return EXACT['porque solo dices eso']
    if s.startswith('no tienes buena inteligencia') or s == 'no entiendes':
        return 'A veces me faltan patrones para entender una frase. No tengo conversación general como un LLM, pero puedo seguir el contexto y pedirte justo el dato que falta.'
    if s.startswith('perfecto') or s.startswith('claro'):
        return _pick((
            'Perfecto, te sigo. ¿Qué hacemos ahora?',
            'Va. ¿Cuál es el siguiente paso?',
            'De acuerdo. Dime qué sigue.',
            'Listo. Te escucho.',
        ), context)
    if s.startswith('gracias'):
        return _pick((
            '¡De nada! ¿Te ayudo con algo más?',
            'Con gusto. ¿Algo más?',
            'Para eso estoy. ¿Seguimos?',
            'No hay de qué. Dime si necesitas algo más.',
        ), context)
    if re.fullmatch(r'(?:quien eres|who are you)', s):
        return 'Soy CLIBOT, un asistente local para Linux. Trabajo offline con reglas y operaciones verificables.'
    if re.fullmatch(r'(?:buenos dias|buenas tardes|buenas noches|que tal)', s):
        return _pick(EXACT.get(s, ('¡Hola! Todo bien por aquí. ¿Qué necesitas?',)), context)
    if re.search(r'\b(dime|explica)\b.*\b(mejor forma|mas claro|en palabras sencillas)\b.*\b(puedes hacer|capacidades)\b', s):
        return 'Puedo ayudarte en estas áreas: revisar el sistema y la hora; consultar RAM, disco, red y servicios; buscar, leer, crear y mover archivos; abrir aplicaciones y páginas; ejecutar programas y comandos con confirmación; hacer cálculos; y realizar comprobaciones de seguridad autorizadas. Si me dices el objetivo, te indico el dato que necesito antes de actuar.'
    if re.search(r'\b(que puedes hacer|que sabes hacer|what can you do)\b', s):
        return None
    if re.search(r'\b(puedes|puede)\b.*\b(crear|hacer)\b.*\b(archivo|archivos|files?)\b', s):
        return 'Sí. Puedo crear un archivo vacío o de texto y decirte la ruta. Dime el nombre y, si no quieres usar la carpeta actual, también la carpeta de destino.'
    if re.search(r'\b(que permisos tienes|que permisos tienes tu|permisos de llmah)\b', s):
        return 'No tengo permisos propios: el programa usa los de tu usuario actual. No elevo privilegios por mi cuenta; las operaciones que los requieren deben fallar o pedir una vía explícita.'
    if re.search(r'\b(cuantos anos tienes|que edad tienes)\b', s):
        return 'No tengo edad; soy un programa. Si quieres, sí puedo decirte la fecha y hora del sistema.'
    if re.search(r'\b(no me gusta|no quiero)\b.*\b(respuestas?(?: sean| son| estan)? predefinidas|respuestas de plantilla|respuestas tan repetidas)\b', s):
        return 'Lo entiendo. Sin un modelo local no puedo improvisar como una persona, pero sí puedo variar las respuestas, recordar el resultado anterior y preguntarte por el dato concreto que falte.'
    if re.fullmatch(r'(?:me gusta|me gusta llmah|me gustas)', s):
        return _pick((
            '¡Gracias! Me alegra que te guste. ¿Qué te gustaría hacer ahora?',
            'Qué bueno. Seguimos mejorando. ¿Qué probamos?',
            'Gracias. Me alegra. ¿Qué sigue?',
        ), context)
    if re.search(r'\b(eso puedes hacer|puedes hacer eso|puedes hacerlo)\b', s):
        return 'Sí, puedo hacer varias tareas locales. Dime cuál quieres probar —por ejemplo buscar algo, ver la hora o crear un archivo— y te digo si está disponible antes de ejecutarla.'
    if re.search(r'\b(me gustas|me caes bien|eres genial|me gusta)\b', s):
        return _pick((
            '¡Gracias! Me alegra que te guste hablar conmigo. ¿Qué hacemos ahora?',
            'Qué amable. Seguimos. ¿Qué necesitas?',
            'Gracias. Me alegra servirte.',
        ), context)
    if re.search(r'\b(no suenan natural|suenas poco natural|no suenas natural|respuestas poco naturales|entiendes horrible|entiendes mal|que mielda)\b', s):
        return 'Sí, ahí me trabé 😅. No tengo conversación libre como un LLM, pero puedo seguir el contexto mejor. Dime qué querías hacer y lo intento de otra forma.'
    if re.search(r'\b(quiero buscar|buscar algo en google|busca algo en google)\b', s):
        return None
    if re.search(r'\b(predeterminado|por defecto)\b', s) and re.search(r'\b(confirm|pregunt|y|si|sí)\b', s):
        return 'Listo: al abrir una página, puedes pulsar Enter para aceptar. Para ejecutar comandos o cambiar archivos seguiré pidiendo una confirmación explícita.'
    if re.fullmatch(r'(?:bruh|bro|lol|jaja+)', s):
        return _pick(('Jaja, aquí ando. ¿Qué necesitas?', 'Jaja. ¿Qué sigue?', '😄 Dime.'), context)
    if re.search(r'\b(interfaz|terminal)\b', s) and re.search(r'\b(fe[oa]|horrible|fea|feo)\b', s):
        return 'Gracias por decírmelo. Estoy puliendo la terminal para que se sienta más ágil y clara. ¿Qué parte te gustaría mejorar primero?'

    # 3) Reglas ampliadas (patrones con variantes)
    for rx, answers in _COMPILED:
        if rx.search(s):
            return _pick(answers, context)

    return None


def unknown_reply(text, context=None):
    """A varied, candid fallback that avoids repeating a fixed error sentence."""
    s = normalize(text).strip(' .!?¿¡')
    if re.search(r'\b(por que|porque)\b', s):
        options = (
            '¿Qué parte quieres que explique?',
            '¿A qué te refieres?',
            'No me quedó claro el motivo. ¿Puedes darme más contexto?',
            '¿Qué parte te intriga más?',
            'Dime a qué cosa te refieres y lo aclaramos.',
        )
    elif '?' in text or re.search(r'\b(que|como|por que|quien|cuando|donde|cual|cuanto)\b', s):
        options = (
            'No entendí la pregunta. ¿Puedes reformularla?',
            '¿Qué tema tienes en mente?',
            'Ahí me perdí. ¿Puedes decirlo con otras palabras?',
            'No tengo esa respuesta en mis reglas. ¿Quieres que la busque en la web?',
            'No estoy segura de qué buscas. Dame un ejemplo.',
            'Esa pregunta me queda grande sin más contexto. ¿Me das el objetivo?',
        )
    elif len(s.split()) <= 2:
        options = (
            '¿Podrías darme un poco más de contexto?',
            'No entendí. ¿Qué necesitas exactamente?',
            'Dime un poco más y lo intento.',
            'Frase corta; necesito más detalle.',
        )
    else:
        options = (
            'No reconocí la petición. ¿Qué quieres lograr?',
            'No entendí. ¿Qué necesitas?',
            'No tengo una regla para eso todavía. Cuéntame el objetivo.',
            'Eso no lo reconozco aún. ¿Puedes explicarlo de otra forma?',
            'Me falta algo de contexto. ¿Qué quieres que haga?',
            'No lo capté. Dime el resultado que esperas.',
        )
    return _choice(options, context)